select ok(not exists(select 1 from public.benefit_redemption_admissions_v1 where redemption_id=(select(v->>'redemption_id')::uuid from manual25a where k='legacy')),'real pre-upgrade reservation receives no invented admission');
select is(private.benefit_admitted_fulfillment_evidence_v1((select(v->>'redemption_id')::uuid from manual25a where k='legacy')),null::text,'legacy reservation cannot silently delegate manual fulfillment');
select pg_temp.actor25a(1);set local role authenticated;
insert into manual25a values('policy',pg_temp.propose25a(1,'GLOBAL_VERSION',3,2));
select pg_temp.actor25a(2);
select public.decide_benefit_admission_policy_v1((select(v->>'policy_id')::uuid from manual25a where k='policy'),(select v->>'content_hash'from manual25a where k='policy'),true,'TEST_25a_APPROVAL','TEST independent policy after actual upgrade');
select pg_temp.actor25a(3);
select is((public.get_benefit_admission_availability_v1('b25a0000-0000-4000-8000-000000000001','f25a0000-0000-4000-8000-000000000001')->>'quota_remaining_units'),'2','legacy reservation already consumes quota before regularisation');
insert into manual25a values('new',pg_temp.reserve25a(1,1,1,'TEST-25a-native-after-upgrade'));
reset role;
insert into manual25a select 'old-snapshot',to_jsonb(r)from public.benefit_redemptions r where id=(select(v->>'redemption_id')::uuid from manual25a where k='legacy');
insert into manual25a values('credit-movements',jsonb_build_object('count',(select count(*)from public.credit_lot_movements where organization_id='b25a0000-0000-4000-8000-000000000001')));
select pg_temp.actor25a(1);set local role authenticated;
insert into manual25a values('legacy-context',public.get_admin_benefit_legacy_admissions_v1('f25a0000-0000-4000-8000-000000000001'));
select is((select jsonb_array_length(v->'items')from manual25a where k='legacy-context'),1,'upgrade console exposes exactly the unadmitted historical reservation');
insert into manual25a values('regularisation',public.propose_legacy_benefit_admission_v1((select(v->>'redemption_id')::uuid from manual25a where k='legacy'),(select v#>>'{items,0,context,redemption_hash}'from manual25a where k='legacy-context'),(select(v->>'policy_id')::uuid from manual25a where k='policy'),'TEST_25a_LEGACY_SOURCE','TEST explicit review of the old reservation and human delegation','a25a9000-0000-4000-8000-000000000001'));
select throws_ok($$select public.decide_legacy_benefit_admission_v1((select(v->>'proposal_id')::uuid from manual25a where k='regularisation'),(select v->>'content_hash'from manual25a where k='regularisation'),true,'TEST_25a_REVIEW','TEST self review forbidden')$$,'42501','BENEFIT_POLICY_INDEPENDENT_REVIEW_REQUIRED','regularisation requester cannot approve their own old reservation');
select pg_temp.actor25a(2);
select is((public.decide_legacy_benefit_admission_v1((select(v->>'proposal_id')::uuid from manual25a where k='regularisation'),(select v->>'content_hash'from manual25a where k='regularisation'),true,'TEST_25a_REVIEW','TEST independent exact old-reservation review')->>'decision'),'APPROVE','different Finance actor approves targeted historical admission');
reset role;
select is((select to_jsonb(r)from public.benefit_redemptions r where id=(select(v->>'redemption_id')::uuid from manual25a where k='legacy')),(select v from manual25a where k='old-snapshot'),'regularisation rewrites no original redemption field or status');
select is((select count(*)::text from public.credit_lot_movements where organization_id='b25a0000-0000-4000-8000-000000000001'),(select v->>'count'from manual25a where k='credit-movements'),'regularisation reserves and consumes no additional credit');
select is(private.benefit_admitted_fulfillment_evidence_v1((select(v->>'redemption_id')::uuid from manual25a where k='legacy')),'HUMAN_OPERATOR_REPORT_AND_INDEPENDENT_CLIENT_RECEIPT_V1','manual authority exists only after genuine independent review');
select pg_temp.actor25a(3);set local role authenticated;
select is((public.get_benefit_admission_availability_v1('b25a0000-0000-4000-8000-000000000001','f25a0000-0000-4000-8000-000000000001')->>'quota_remaining_units'),'1','old and new units count once each after regularisation');
select is((public.get_benefit_admission_availability_v1('b25a0000-0000-4000-8000-000000000001','f25a0000-0000-4000-8000-000000000001')->>'capacity_remaining_units'),'0','capacity is not reset by historical regularisation');
select public.release_benefit_credits((select(v->>'redemption_id')::uuid from manual25a where k='legacy'),'TEST_TRUE_RELEASE','TEST-25a-release-legacy');
select is((public.get_benefit_admission_availability_v1('b25a0000-0000-4000-8000-000000000001','f25a0000-0000-4000-8000-000000000001')->>'quota_remaining_units'),'2','actual release remains available after upgrade and review');
reset role;
select*from finish();rollback;
